create table MOCK_DATA (
	transaction_id INT,
	card_number VARCHAR(50),
	card_type VARCHAR(16),
	expiration_date DATE,
	cvv INT,
	card_holder_name VARCHAR(50),
	billing_address VARCHAR(50),
	billing_city VARCHAR(50),
	billing_state VARCHAR(50),
	billing_postal_code VARCHAR(50),
	billing_country VARCHAR(50),
	transaction_amount DECIMAL(7,2),
	transaction_date DATE,
	merchant_name VARCHAR(50),
	merchant_category VARCHAR(13),
	transaction_description TEXT,
	transaction_type VARCHAR(12),
	currency_code VARCHAR(50),
	exchange_rate DECIMAL(5,4),
	conversion_amount DECIMAL(7,2),
	conversion_date DATE,
	transaction_status VARCHAR(8),
	authorization_code TEXT,
	payment_gateway VARCHAR(50),
	transaction_reference_number TEXT,
	customer_name VARCHAR(50),
	customer_email VARCHAR(50),
	customer_phone VARCHAR(50),
	customer_address VARCHAR(50),
	customer_city VARCHAR(50),
	customer_state VARCHAR(50),
	customer_postal_code VARCHAR(50)
);
